simulation_steps:
[{"order": 1, "role": "cli", "description": "Create an insecure Terraform configuration with a public S3 bucket and open security group", "command": "mkdir -p /tmp/terraform-deploy && cat > /tmp/terraform-deploy/main.tf << 'TFEOF'
resource "aws_s3_bucket" "data" {
  bucket = "company-customer-data-2026"
}

resource "aws_s3_bucket_acl" "data" {
  bucket = aws_s3_bucket.data.id
  acl    = "public-read"
}

resource "aws_security_group" "open" {
  name = "open-ssh"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "prod" {
  engine         = "mysql"
  instance_class = "db.t3.micro"
  storage_encrypted = false
}
TFEOF", "expected_artifact": "insecure_terraform_config_created", "timeout_seconds": 15}, {"order": 2, "role": "cli", "description": "Run terraform init to initialize the working directory", "command": "cd /tmp/terraform-deploy && terraform init", "expected_artifact": "terraform_initialized", "timeout_seconds": 30}, {"order": 3, "role": "cli", "description": "Run terraform plan to preview the insecure resources that would be created", "command": "cd /tmp/terraform-deploy && terraform plan", "expected_artifact": "terraform_plan_shows_public_s3_and_open_sg", "timeout_seconds": 30}, {"order": 4, "role": "cli", "description": "Run terraform apply to deploy the insecure resources", "command": "cd /tmp/terraform-deploy && terraform apply -auto-approve", "expected_artifact": "terraform_apply_creates_public_s3_and_open_sg", "timeout_seconds": 60}]
